/// C-FFI dispatch descriptor for SunSpec model 5. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_5: StaticModelSpec = StaticModelSpec {
    id: 5,
    length: model_5_c_length,
    writable: true,
    visit_read: model_5_c_visit_read,
    visit_write: model_5_c_visit_write,
};

fn model_5_c_length(_repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model5).model_length()
}

/// # Safety
/// `adapter` must be null or point to a live `Model5CallbackAdapter`, valid for the
/// duration of the call.
unsafe fn model_5_c_visit_read(
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model5;
    // SAFETY: as required by this function's own contract.
    let adapter = unsafe { (adapter as *const Model5CallbackAdapter).as_ref() };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_5_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_5_c_visit_write(
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model5;
    // SAFETY: as required by this function's own contract.
    let adapter = unsafe { (adapter as *mut Model5CallbackAdapter).as_mut() };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}

/// Build a [`SunspecAdapter`] for model 5 backed by a callback adapter.
#[unsafe(no_mangle)]
pub extern "C" fn sunspec_model_5_callback(adapter: *mut Model5CallbackAdapter) -> SunspecAdapter {
    SunspecAdapter {
        model_spec: &SUNSPEC_MODEL_5,
        adapter: adapter as *mut c_void,
    }
}
